content.css:
.atlyn-heatmap {
  --background: #ffffff;
  --foreground: #172b3a;
  --muted: #526472;
  --border: #c8d2da;
  --focus: #0078d4;
  --header: #eff4f8;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  overflow: hidden;
  background: var(--background);
  color: var(--foreground);
  font-family: "Segoe UI", Arial, sans-serif;
  line-height: 1.35;
}
.atlyn-heatmap *,
.atlyn-heatmap *::before,
.atlyn-heatmap *::after {
  box-sizing: border-box;
}
.atlyn-heatmap button,
.atlyn-heatmap summary {
  font: inherit;
  color: inherit;
}
.atlyn-heatmap button {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: 3px;
  padding: 3px 7px;
  cursor: pointer;
}
.atlyn-heatmap button:disabled {
  opacity: 0.6;
  cursor: default;
}
.atlyn-heatmap :focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}
.atlyn-heatmap .heading {
  flex: 0 0 auto;
  max-height: 40%;
  overflow: auto;
  padding: 5px 7px;
  border-block-end: 1px solid var(--border);
  scrollbar-gutter: stable;
}
.atlyn-heatmap .toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  align-items: center;
}
.atlyn-heatmap .title {
  font-weight: 650;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.atlyn-heatmap .semantics {
  margin-block-start: 3px;
}
.atlyn-heatmap .legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  margin-block-start: 4px;
}
.atlyn-heatmap .ramp {
  display: inline-flex;
  direction: ltr;
  width: 90px;
  height: 12px;
  border: 1px solid var(--border);
}
.atlyn-heatmap .swatch {
  flex: 1;
}
.atlyn-heatmap .scope-warning {
  font-weight: 600;
}
.atlyn-heatmap .viewport {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  overflow: auto;
  position: relative;
  isolation: isolate;
}
.atlyn-heatmap table {
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 2px;
  min-width: 100%;
}
.atlyn-heatmap th,
.atlyn-heatmap td {
  padding: 3px 6px;
  height: var(--cell-height);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border: 1px solid transparent;
  text-align: center;
  cursor: pointer;
  position: relative;
}
.atlyn-heatmap th {
  background: var(--header);
  color: var(--foreground);
  font-weight: 600;
  border-color: var(--border);
}
.atlyn-heatmap thead th {
  position: sticky;
  top: 0;
  z-index: 3;
  height: var(--cell-height);
}
.atlyn-heatmap tbody th {
  position: sticky;
  inset-inline-start: 0;
  z-index: 2;
  text-align: start;
}
.atlyn-heatmap thead th:first-child {
  inset-inline-start: 0;
  z-index: 4;
}
.atlyn-heatmap td {
  border-color: var(--border);
}
.atlyn-heatmap td[data-state="blank"] {
  background: var(--header);
}
.atlyn-heatmap td[data-state="absent"],
.atlyn-heatmap td[data-state="unloaded"] {
  background: repeating-linear-gradient(135deg, var(--background), var(--background) 5px, var(--header) 5px, var(--header) 7px);
}
.atlyn-heatmap td[data-state="invalid"],
.atlyn-heatmap td[data-state="unavailable"] {
  border-style: dashed;
}
.atlyn-heatmap [aria-disabled="true"] {
  cursor: default;
}
.atlyn-heatmap [aria-selected="true"] {
  box-shadow: inset 0 0 0 3px currentColor;
}
.atlyn-heatmap td:focus-visible {
  outline: 3px double currentColor;
  outline-offset: -6px;
}
.atlyn-heatmap .highlighted::after {
  content: "";
  position: absolute;
  inset-block-start: 3px;
  inset-inline-end: 3px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
}
.atlyn-heatmap .highlighted {
  outline: 1px solid currentColor;
  outline-offset: -3px;
}
.atlyn-heatmap .dimmed {
  border-style: dashed;
}
.atlyn-heatmap .footer {
  flex: 0 0 auto;
  max-height: 26%;
  overflow: auto;
  padding: 4px 7px;
  border-block-start: 1px solid var(--border);
}
.atlyn-heatmap .status {
  font-weight: 600;
}
.atlyn-heatmap .notice {
  margin-block: 2px;
}
.atlyn-heatmap .legal {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font: inherit;
}
.atlyn-heatmap .empty {
  padding: 12px;
  overflow: auto;
}
.atlyn-heatmap .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.atlyn-heatmap.tiny .heading,
.atlyn-heatmap.tiny .footer {
  display: none;
}
.atlyn-heatmap.tiny .empty {
  min-height: 100%;
  display: grid;
  place-items: center;
  padding: 8px;
  text-align: center;
}
.atlyn-heatmap.compact .toolbar {
  flex-wrap: nowrap;
  gap: 4px;
}
.atlyn-heatmap.high-contrast {
  --header: var(--background);
  --muted: var(--foreground);
}
.atlyn-heatmap.high-contrast .dimmed {
  opacity: 1;
  border-style: dashed;
}
.atlyn-heatmap.high-contrast .highlighted {
  outline-width: 2px;
}
.atlyn-heatmap.high-contrast td {
  background: var(--background) !important;
  color: var(--foreground) !important;
}
@media (prefers-reduced-motion: reduce) {
  .atlyn-heatmap *,
  .atlyn-heatmap *::before,
  .atlyn-heatmap *::after {
    scroll-behavior: auto;
    transition: none;
    animation: none;
  }
}
